def check(k):
    for n in range(int(k), 1001):
        lhs = n // k
        rhs = (n * (k - 6)) / k
        if not (lhs >= rhs):
            return False, n, lhs, rhs
    return True, None, None, None

import numpy as np
for i in range(1, 1000):
    k = 6 + i/1000
    res, n, lhs, rhs = check(k)
    if not res:
        print(f"k={k} fails at n={n} (lhs={lhs}, rhs={rhs})")
        break
    else:
        pass

import math

def is_valid(k):
    if k <= 6: return True
    # Condition: qk / (ceil((q+1)k) - 1) >= k - 6 for all q >= 1
    for q in range(1, 10000):
        n_max = math.ceil((q + 1) * k) - 1
        if n_max < k:
            continue
        if q * k / n_max < k - 6 - 1e-9:
            return False
    return True

# Find max k in [6, 7]
low = 6.0
high = 7.0
for _ in range(50):
    mid = (low + high) / 2
    if is_valid(mid):
        low = mid
    else:
        high = mid
print(low)

