def find_k_refined():
    K = []
    for n in range(1, 500):
        m_n = 1
        while True:
            if (m_n // 6) + m_n >= n:
                break
            m_n += 1
        K.append(6 * n / m_n)

    best_k = 0
    # The max k will be one of the K_n values.
    # because the condition k <= K_n for all n >= k is a set of inequalities.
    # The maximum k satisfying k <= K_n for all n >= k is k = min_{n >= k} K_n.
    # This min value must be one of the K_n.
    for i in range(len(K)):
        k_val = K[i]
        possible = True
        for j in range(len(K)):
            n_val = j + 1
            if n_val >= k_val - 1e-9:
                if K[j] < k_val - 1e-9:
                    possible = False
                    break
        if possible:
            best_k = max(best_k, k_val)
    return best_k

